class Solution {
    private int reverse(int value){
        int result=0;
        while(value>0){
            result=result*10+value%10;
            value/=10;
        }
        return result;
    }
    public boolean sumOfNumberAndReverse(int num){
        for(int value=0;value<=num;value++)if(value+reverse(value)==num)return true;
        return false;
    }
}

code.kotlin:
class Solution {
    fun sumOfNumberAndReverse(num:Int):Boolean{
        for(value in 0..num){
            var x=value;
            var reversed=0;
            while(x>0){
                reversed=reversed*10+x%10;
                x/=10
            };
            if(value+reversed==num)return true
        };
        return false
    }
}

